            .attribute(value:PageAttribute::class(value:"message"))
            .text(value:label("Choose a module to explore.")).close()
            .open(element:PageElement::Paragraph).attribute(value:PageAttribute::view(value:ui.loading))
            .attribute(value:PageAttribute::class(value:"message"))
            .text(value:label("Loading source…")).close()
            .open(element:PageElement::Pre).attribute(value:PageAttribute::view(value:ui.error))
            .attribute(value:PageAttribute::node(value:ui.error_text))
            .attribute(value:PageAttribute::class(value:"message error")).close()
            .open(element:PageElement::Div).attribute(value:PageAttribute::class(value:"source-lines"))
            .attribute(value:PageAttribute::view(value:ui.ready))
            .open(element:PageElement::Pre).attribute(value:PageAttribute::class(value:"line-numbers"))
            .attribute(value:PageAttribute::node(value:ui.gutter)).close()
            .open(element:PageElement::Pre).attribute(value:PageAttribute::class(value:"source-code"))
            .attribute(value:PageAttribute::node(value:ui.code)).close()
            .close().close().close()
            .open(element:PageElement::Template).attribute(value:PageAttribute::template(value:ui.code))
            .open(element:PageElement::Span)
            .open(element:PageElement::Span).attribute(value:PageAttribute::node(value:ui.token))
            .attribute(value:PageAttribute::class_token(slot:ui.ty,value:"hl-ty"))
            .attribute(value:PageAttribute::class_token(slot:ui.function,value:"hl-function"))
            .attribute(value:PageAttribute::class_token(slot:ui.property,value:"hl-property"))
            .attribute(value:PageAttribute::class_token(slot:ui.variable,value:"hl-variable"))
            .attribute(value:PageAttribute::class_token(slot:ui.keyword,value:"hl-keyword"))
            .attribute(value:PageAttribute::class_token(slot:ui.comment,value:"hl-comment"))
            .attribute(value:PageAttribute::class_token(slot:ui.string,value:"hl-string"))
            .attribute(value:PageAttribute::class_token(slot:ui.number,value:"hl-number"))
            .close().close().close().finish_component()
    }

    fn initial() -> SourceState uses (InitialState) {
        let patch=allocate_component_buffer(capacity:PATCH_CAPACITY)
        let control=allocate_component_buffer(capacity:CONTROL_CAPACITY)
        let url=allocate_component_buffer(capacity:URL_CAPACITY)
        let content=allocate_component_buffer(capacity:CONTENT_CAPACITY)
        let gutter=allocate_component_buffer(capacity:GUTTER_CAPACITY)
        publish_load_command(control:control.ptr,revision:0,request:0,url_len:0,binary:false,active:false)
        SourceState { patch_ptr:patch.ptr,control_ptr:control.ptr,url_ptr:url.ptr,content_ptr:content.ptr,
            gutter_ptr:gutter.ptr,url_len:0,content_len:0,request:0,status:SourceStatus::Empty,
            connected:false,prevent_default:false }
    }

    fn load_resources(self) -> u32 uses (ScopedTask) {
        with (
            AsyncEventSource<WasmBackend,ActorNotification> = BrowserActorNotifications::new(),
            Select<WasmBackend,u32> = Resumable {},
            PendingCancellation<WasmBackend> = Resumable {},
            ActorSink<WasmBackend,ComponentEvent<InspectorAction,InspectorTask>> = BrowserActorSink {},
            Suspend<WasmBackend,u32> = Resumable {},
        ) {
            load_inspector_resources(control:self.control_ptr,url:self.url_ptr,content:self.content_ptr)
        }
    }

    fn receive(self,event:own ComponentEvent<InspectorAction,InspectorTask>) -> SourceState uses (ResidentTransition) {
        let mut connected=self.connected
        let mut url_len=self.url_len
        let mut content_len=self.content_len
        let mut request=self.request
        let mut status=self.status
        let mut prevent_default=false
        match event.kind {
            ComponentEventKind::Connected => { connected=true }
            ComponentEventKind::Disconnected => {
                connected=false
                publish_load_command(control:self.control_ptr,revision:request+1,request:request,
                    url_len:url_len,binary:false,active:false)
                BrowserActorNotifications::new().notify()
            }
            ComponentEventKind::Activate => {
                if connected {
                    match event.target {
                        InspectorAction::Source => {
                            let copied=Utf8Buffer::empty(ptr:self.url_ptr,capacity:URL_CAPACITY).replace_browser(event.text)
                            if copied.valid && !copied.truncated {
                                url_len=copied.buffer.len()
                                request=request+1
                                content_len=0
                                status=SourceStatus::Loading
                                prevent_default=true
                                publish_load_command(control:self.control_ptr,revision:request,request:request,
                                    url_len:url_len,binary:false,active:true)
                                BrowserActorNotifications::new().notify()
                            }
                        }
                        _ => {}
                    }
                }
            }
            ComponentEventKind::TaskMessage => {
                if connected && event.task.request==request {
                    match event.target {
                        InspectorAction::ResourceComplete => {
                            content_len=event.task.content_len
                            status=if event.task.status>=200 && event.task.status<300 { SourceStatus::Ready } else { SourceStatus::Error }
                        }
                        InspectorAction::ResourceFailed => { content_len=event.task.content_len
                            status=SourceStatus::Error }
                        _ => {}
                    }
                }
            }
            _ => {}
        }
        SourceState { patch_ptr:self.patch_ptr,control_ptr:self.control_ptr,url_ptr:self.url_ptr,
            content_ptr:self.content_ptr,gutter_ptr:self.gutter_ptr,url_len:url_len,content_len:content_len,
            request:request,status:status,connected:connected,prevent_default:prevent_default }
    }

    fn project(self) -> ComponentPatch uses (ProjectState) {
        let ui=<SourceParts as ComponentSchema>::component_parts()
        let ready=match self.status { SourceStatus::Ready=>true,_=>false }
        let visible=VisibleParts::none()
            .show_if(target:ui.ready,visible:ready)
            .show_if(target:ui.empty,visible:match self.status { SourceStatus::Empty=>true,_=>false })
            .show_if(target:ui.loading,visible:match self.status { SourceStatus::Loading=>true,_=>false })
            .show_if(target:ui.error,visible:match self.status { SourceStatus::Error=>true,_=>false })
        let requested=Utf8Buffer::with_len(ptr:self.url_ptr,len:self.url_len,capacity:URL_CAPACITY).view()
        let url=if requested.len()>5 && requested.slice(start:requested.len()-5,end:requested.len()).view.equals_literal([46,118,105,101,119]) {
            requested.slice(start:0,end:requested.len()-5).view
        } else {requested}
        let content=Utf8Buffer::with_len(ptr:self.content_ptr,len:self.content_len,capacity:CONTENT_CAPACITY).view()
        let mut writer=ComponentWriter::new(buffer:BrowserBytes { ptr:self.patch_ptr,len:PATCH_CAPACITY })
        if self.url_len>0 {
            writer=writer.set_href(target:ui.raw,value:url.browser_string())
                .set_text(target:ui.title,value:filename(url))
        }
        writer=writer.repeat_begin(region:ui.code)
        if ready {
            let doc=ingot::highlight::document(content)
            let mut at:u32=0
            let mut tokens:u32=0
            while at<doc.text.len() {
                let token=if tokens>=8191 {ingot::highlight::Token {end:doc.text.len(),kind:0}}
                    else {ingot::highlight::next(doc,at)}
                writer=writer.repeat_item(key:at+1)
                    .set_text(target:ui.token,value:doc.text.slice(start:at,end:token.end).view.browser_string())
                    .set_class(target:ui.token,token:ui.ty,enabled:token.kind==1)
                    .set_class(target:ui.token,token:ui.function,enabled:token.kind==2)
                    .set_class(target:ui.token,token:ui.property,enabled:token.kind==3)
                    .set_class(target:ui.token,token:ui.variable,enabled:token.kind==4)
                    .set_class(target:ui.token,token:ui.keyword,enabled:token.kind==5)
                    .set_class(target:ui.token,token:ui.comment,enabled:token.kind==6)
                    .set_class(target:ui.token,token:ui.string,enabled:token.kind==7)
                    .set_class(target:ui.token,token:ui.number,enabled:token.kind==8)
                at=token.end
                tokens=tokens+1
            }
            writer=writer.repeat_end()
                .set_text(target:ui.gutter,value:line_numbers(self.gutter_ptr,doc.text))
        } else {
            writer=writer.repeat_end()
            writer=writer.set_text(target:ui.error_text,value:content.browser_string())
        }
        ComponentPatch::new(visible:visible,focus_target:InspectorAction::Unknown,
            prevent_default:self.prevent_default,commands:writer.finish())
    }
}

