        if ready {
            let doc=ingot::highlight::document(content)
            let mut at:u32=0
            let mut tokens:u32=0
            while at<doc.text.len() {
                let token=if tokens>=8191 {ingot::highlight::Token {end:doc.text.len(),kind:0}}
                    else {ingot::highlight::next(doc,at)}
                writer=writer.repeat_item(key:at+1)
                    .set_text(target:ui.token,value:doc.text.slice(start:at,end:token.end).view.browser_string())
                    .set_class(target:ui.token,token:ui.ty,enabled:token.kind==1)
                    .set_class(target:ui.token,token:ui.function,enabled:token.kind==2)
                    .set_class(target:ui.token,token:ui.property,enabled:token.kind==3)
                    .set_class(target:ui.token,token:ui.variable,enabled:token.kind==4)
                    .set_class(target:ui.token,token:ui.keyword,enabled:token.kind==5)
                    .set_class(target:ui.token,token:ui.comment,enabled:token.kind==6)
                    .set_class(target:ui.token,token:ui.string,enabled:token.kind==7)
                    .set_class(target:ui.token,token:ui.number,enabled:token.kind==8)
                at=token.end
                tokens=tokens+1
            }
            writer=writer.repeat_end()
                .set_text(target:ui.gutter,value:line_numbers(self.gutter_ptr,doc.text))
        } else {
            writer=writer.repeat_end()
            writer=writer.set_text(target:ui.error_text,value:content.browser_string())
        }
        ComponentPatch::new(visible:visible,focus_target:InspectorAction::Unknown,
            prevent_default:self.prevent_default,commands:writer.finish())
    }
}

