//! Fe lexical colors, enriched with compiler-exported SCIP byte ranges.
//! FEH1 packs one semantic class byte per UTF-8 source byte, then exact source.
use std::text::Utf8View
pub struct Document { pub text:Utf8View, pub kinds:Utf8View }
pub struct Token { pub end:u32, pub kind:u32 }
pub fn document(_ raw:Utf8View) -> Document {
    if raw.len()<8 || !raw.slice(start:0,end:5).view.equals_literal([70,69,72,49,10]) {
        return Document {text:raw,kinds:Utf8View::empty()}
    }
    let mut at:u32=5
    let mut count:u32=0
    while at<raw.len() && at<12 && raw.byte(index:at)>=48 && raw.byte(index:at)<=57 {
        let value:u8=raw.byte(index:at)-48
        let wide:u32=value as u32
        count=count*10+wide
        at=at+1
    }
    let start:u32=at+1
    if at>=raw.len() || raw.byte(index:at)!=10 || count>500000 || start+count*2+1!=raw.len() {
        return Document {text:raw,kinds:Utf8View::empty()}
    }
    Document {kinds:raw.slice(start:start,end:start+count).view,
        text:raw.slice(start:start+count+1,end:raw.len()).view}
}
fn letter(_ c:u8) -> bool { (c>=65 && c<=90)||(c>=97 && c<=122)||c==95||c>=128 }
fn digit(_ c:u8) -> bool { c>=48 && c<=57 }
fn name(_ c:u8) -> bool {letter(c)||digit(c)}
pub fn next(_ doc:Document,_ start:u32) -> Token {
    let source=doc.text
    let c=source.byte(index:start)
    let mut end=start+1
    let mut kind:u32=0
    if c==47 && end<source.len() && source.byte(index:end)==47 {
        kind=6
        while end<source.len() && source.byte(index:end)!=10 {end=end+1}
    } else {if c==47 && end<source.len() && source.byte(index:end)==42 {
        kind=6
        end=end+1
        let mut depth:u32=1
        while end<source.len() && depth>0 {
            if end+1<source.len() && source.byte(index:end)==47 && source.byte(index:end+1)==42 {
                depth=depth+1
                end=end+2
            } else {if end+1<source.len() && source.byte(index:end)==42 && source.byte(index:end+1)==47 {
                depth=depth-1
                end=end+2
            } else {end=end+1}}
        }
    } else {if c==34 {
        kind=7
        let mut done=false
        while end<source.len() && !done {
            let value=source.byte(index:end)
            end=end+1
            if value==92 && end<source.len() {end=end+1}
            else {if value==34 {done=true}}
        }
    } else {if digit(c) {
        kind=8
        while end<source.len() && (name(source.byte(index:end))||source.byte(index:end)==46) {end=end+1}
    } else {if letter(c) {
        while end<source.len() && name(source.byte(index:end)) {end=end+1}
        let word=source.slice(start:start,end:end).view
        if keyword(word) {kind=5}
        else {if primitive(word) {kind=1}
        else {if doc.kinds.len()>start {
            let tag=doc.kinds.byte(index:start)
            if tag>=49 && tag<=52 {
                let value:u8=tag-48
                kind=value as u32
            }
        }}}
    } else {
        while end<source.len() && !name(source.byte(index:end)) && source.byte(index:end)!=34 && source.byte(index:end)!=47 {end=end+1}
    }}}}}
    Token {end:end,kind:kind}
